"use client";

import FlightConfirmationModal from "./flight-confirmation-modal";
import { useFlightConfirmation } from "@/context/FlightConfirmationContext";
import { confirmFlight } from "@/lib/api/flightConfirmation";

export default function GlobalFlightConfirmation() {
  const {
    flightConfirmation,
    hideFlightConfirmation,
  } = useFlightConfirmation();

  if (!flightConfirmation.open) return null;

  const handleConfirm = async ({
    batch,
    mode,
  }: {
    batch: string;
    mode: string;
  }) => {
    try {
      console.log("Confirming flight:", {
        flightId: flightConfirmation.flightId,
        batch,
        mode,
      });

      await confirmFlight(
        flightConfirmation.flightId,
        batch,
        mode
      );

      console.log("Flight confirmed successfully");

      hideFlightConfirmation();
    } catch (error) {
      console.error("Failed to confirm flight:", error);
    }
  };

  return (
    <FlightConfirmationModal
      droneId={flightConfirmation.droneId}
      onConfirm={handleConfirm}
    />
  );
}