export const getPendingFlightConfirmations = async () => {
  const response = await fetch(
    `${process.env.NEXT_PUBLIC_API_URL}/api/flight-confirmation/pending`,
    {
      credentials: "include",
    }
  );

  if (!response.ok) {
    throw new Error("Failed to fetch pending flight confirmations");
  }

  return response.json();
};

export const confirmFlight = async (
  flightId: string,
  batch: string,
  mode: string
) => {
  const response = await fetch(
    `${process.env.NEXT_PUBLIC_API_URL}/api/flight-confirmation/${flightId}/confirm`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      credentials: "include",
      body: JSON.stringify({
        batch,
        mode,
      }),
    }
  );

  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.message || "Failed to confirm flight");
  }

  return data;
};